-- 184_rpg_armor.sql
-- DORPG P8：防具系統（五部位依職業各一套＋通用飾品分 5 級，契約見
-- scratchpad/dorpg_p8/{CONTRACT.md,WIRE.md}）。本檔只建表／改約束；6 職業×5 部位×10 級（300）＋
-- 通用飾品 18 效果×5 級（90）共 390 件的 seed 由另一個 Workflow 產生，貼進下方兩對標記之間
-- （刻意放在 rpg_armor_items 建好之後，seed 才有表可插）。
--
-- ⚠️ 使用者手動套用到 Neon，不得自行套用；CREATE TABLE IF NOT EXISTS／索引 IF NOT EXISTS／
-- 約束一律先 DROP IF EXISTS 再重建，可安全重複執行。依規範（db-before-code-push.md）等使用者
-- 確認已套用才能 push 依賴這些新表/約束的程式碼。

-- ---------------------------------------------------------------------------
-- 1) rpg_armor_items：頭盔/手套/衣服/褲裙/鞋子（job_id NOT NULL，每職業各 10 級）＋通用飾品
--    （job_id NULL，18 效果×5 級）共用同一張表（CONTRACT §1）。
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rpg_armor_items (
  id            TEXT PRIMARY KEY,                 -- 防具 <job短碼>_<slot>_t<tier>；飾品 acc_<effect>_t<tier>
  job_id        TEXT NULL REFERENCES rpg_jobs(id), -- NULL＝通用（只有飾品是 NULL）
  slot          TEXT NOT NULL CHECK (slot IN ('helmet','gloves','armor','legs','boots','accessory')),
  tier          INT NOT NULL CHECK (tier BETWEEN 1 AND 10), -- 防具 1..10；飾品 1..5（應用層再收緊，見 armor.go ArmorRow.Validate）
  name          TEXT NOT NULL,
  rarity        TEXT NOT NULL DEFAULT 'common',   -- 防具 t1-3 common／4-6 rare／7-9 epic／10 legendary；飾品 t1 common／t2-3 rare／t4 epic／t5 legendary
  level_req     INT NOT NULL DEFAULT 1,           -- 防具 tier→1/10/20/30/40/50/60/70/80/90；飾品 tier→1/20/40/60/80
  profile       JSONB NOT NULL DEFAULT '{}',      -- ArmorProfile，見 internal/rpg/armor.go；缺欄位＝中性值
  description   TEXT NOT NULL DEFAULT '',
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order    INT NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_rpg_armor_items_job_slot_tier ON rpg_armor_items(job_id, slot, tier);

-- >>> ARMOR SEED (generated) >>>
-- DORPG P8：rpg_armor_items (390 = 300 防具 + 90 飾品)
-- 產生自 scratchpad/dorpg_p8/armor_all.json（已通過 validate_armor.py，0 錯誤）

ON CONFLICT (id) DO UPDATE SET
  job_id = EXCLUDED.job_id,
  slot = EXCLUDED.slot,
  tier = EXCLUDED.tier,
  name = EXCLUDED.name,
  rarity = EXCLUDED.rarity,
  level_req = EXCLUDED.level_req,
  profile = EXCLUDED.profile,
  description = EXCLUDED.description,
  is_active = EXCLUDED.is_active,
  sort_order = EXCLUDED.sort_order;

-- <<< ARMOR SEED <<<

-- ---------------------------------------------------------------------------
-- 2) player_equipment：slot 值域由僅 'weapon' 擴充成八格（武器＋五部位防具＋兩格飾品，
--    CONTRACT §1）；item_id 原本 FK 到 rpg_weapons，現在同一欄位視 slot 可能指向 rpg_weapons
--    或 rpg_armor_items，無法用單一 FK 表達，移除 FK 改由應用層依 slot 驗證 item 存在
--    （weapon 查 rpg_weapons，其餘查 rpg_armor_items；查無 item → 視為未裝備，不 500，見
--    internal/rpg/equipment.go）。兩條約束都先 DROP IF EXISTS 再重建/略過，整段可安全重複執行。
-- ---------------------------------------------------------------------------

ALTER TABLE player_equipment DROP CONSTRAINT IF EXISTS player_equipment_item_id_fkey;
ALTER TABLE player_equipment DROP CONSTRAINT IF EXISTS player_equipment_slot_check;
ALTER TABLE player_equipment ADD CONSTRAINT player_equipment_slot_check
  CHECK (slot IN ('weapon','helmet','gloves','armor','legs','boots','accessory1','accessory2'));

